def _extract_jira_ref(detail: dict[str, Any], commits: list[dict[str, Any]]) -> str | None:
    """
    Extract Jira reference using priority order: title, branch, body, commit messages.

    Security note:
    - Only reads textual metadata already available in GitHub API payloads.
    """
