def _resolve_project_from_repo(db: Session, repository: str) -> Project | None:
    """Resolve project by exact or short repository name mapping."""
    canonical = _canonical_repo_name(repository).lower()
    short_name = canonical.split("/", 1)[1] if "/" in canonical else canonical

    projects = db.query(Project).filter(Project.repository_name.isnot(None)).all()
    for project in projects:
        repo_name = (project.repository_name or "").strip()
        if not repo_name:
            continue
        normalized = _canonical_repo_name(repo_name).lower()
        normalized_short = normalized.split("/", 1)[1] if "/" in normalized else normalized
        if canonical == normalized or short_name == normalized_short:
            return project
    return None


