def _sync_and_commit(
    db: Session,
    repositories: list[str],
    state: str,
    explicit_release_id: int | None = None,
    explicit_project_id: int | None = None,
) -> dict[str, Any]:
    """Sync one or many repositories and commit once for consistency."""
    logger.info("GitHub PR synchronization started for %s repositories", len(repositories))
    total_fetched = 0
    total_inserted = 0
    total_updated = 0
    total_skipped = 0
    per_repo: list[dict[str, Any]] = []

    try:
        for repository in repositories:
            result = _sync_repository(
                db,
                repository=repository,
                state=state,
                explicit_release_id=explicit_release_id,
                explicit_project_id=explicit_project_id,
            )
            total_fetched += result["fetched"]
            total_inserted += result["inserted"]
            total_updated += result["updated"]
            total_skipped += result["skipped"]
            per_repo.append(result)

        db.commit()
    except Exception as exc:  # noqa: BLE001
        db.rollback()
        logger.exception("GitHub PR synchronization failed and transaction was rolled back")
        return {
            "state": state,
            "repositories_processed": len(repositories),
            "fetched": total_fetched,
            "inserted": total_inserted,
            "updated": total_updated,
            "skipped": total_skipped,
            "details": per_repo,
            "error": str(exc),
        }

    if explicit_release_id is not None:
        release = db.query(Release).filter(Release.release_id == explicit_release_id).first()
        if release:
            release.total_prs = db.query(PullRequest).filter(PullRequest.release_id == explicit_release_id).count()
            db.commit()

    logger.info(
        "GitHub PR synchronization completed. fetched=%s inserted=%s updated=%s skipped=%s",
        total_fetched,
        total_inserted,
        total_updated,
        total_skipped,
    )

    return {
        "state": state,
        "repositories_processed": len(repositories),
        "fetched": total_fetched,
        "inserted": total_inserted,
        "updated": total_updated,
        "skipped": total_skipped,
        "details": per_repo,
    }


# Generated by GitHub Copilot
def sync_pull_requests(db: Session, release_id: int, state: str = "all") -> dict[str, Any]:
    """Sync GitHub pull requests into local DB for a specific release."""
    release = db.query(Release).filter(Release.release_id == release_id).first()
    if not release:
        return {"message": "Release not found"}

    repo_full_name = _repo_from_release(db, release_id)
    if not repo_full_name:
        return {"message": "Repository is not configured for this release/project"}

    result = _sync_and_commit(
        db,
        repositories=[repo_full_name],
        state=state,
        explicit_release_id=release_id,
        explicit_project_id=release.project_id,
    )
    result["release_id"] = release_id
    result["repository"] = repo_full_name
    return result


