def remap_all_pull_requests_to_release(db: Session, release_id: int) -> dict[str, Any]:
    """
    Force-map all stored pull requests to one release id.

    This utility supports one-time migration or explicit operational remapping.
    """
    release = db.query(Release).filter(Release.release_id == release_id).first()
    if not release:
        return {"message": "Release not found"}

    rows = db.query(PullRequest).all()
    total = len(rows)
    updated = 0

    for row in rows:
        if row.release_id != release_id:
            row.release_id = release_id
            updated += 1

    release.total_prs = total
    db.commit()

    logger.info(
        "All pull requests remapped to release_id=%s. total=%s updated=%s",
        release_id,
        total,
        updated,
    )

    return {
        "release_id": release_id,
        "total_pull_requests": total,
        "remapped": updated,
        "unchanged": total - updated,
    }


